final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
String poolEntry = readConstantPoolEntry(constantPoolEntryIndex);
if (!poolEntry.startsWith("CONSTANT_Utf8")) {
throw new IllegalArgumentException("Invalid constant pool entry index: " + constantPoolEntryIndex);
}
// Extract the length and bytes from the CONSTANT_Utf8 entry
int length = Integer.parseInt(poolEntry.split(":")[1].replace("-", ""));
String bytes = poolEntry.substring(poolEntry.indexOf("-") + 1, poolEntry.indexOf("<"));

// Convert the bytes to a string using the provided char buffer
int charsWritten = 0;
for (int i = 0; i < length; i++) {
charBuffer[i] = (char) Integer.parseInt(bytes.split("-")[i], 16);
charsWritten++;
}

// Trim the char buffer to the correct size
charBuffer = Arrays.copyOf(charBuffer, charsWritten);
return new String(charBuffer);
}

