private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds) {
    List<Integer> suffixSumList = new ArrayList<>();
    Long sumOfBounds = 0L;

    for (int i = 0; i < bounds.size(); i++) {
        int current = bounds.get(i);
        suffixSumList.add(current);
        sumOfBounds += current;
    }

    for (int i = 1; i < suffixSumList.size(); i++) {
        suffixSumList.set(i, suffixSumList.get(i - 1) + suffixSumList.get(i));
    }

    return new Pair<>(suffixSumList, sumOfBounds);
}

